import React, {
  useCallback,
  useEffect,
  useMemo,
  useState,
} from 'react';

import {
  FiEye,
  FiTrash2,
  FiSearch,
  FiRefreshCw,
  FiX,
  FiUsers,
  FiMail,
  FiPhone,
  FiBookOpen,
  FiCalendar,
} from 'react-icons/fi';

import api, {
  getApiErrorMessage,
} from '../../services/api';

import {
  useLanguage,
} from '../../contexts/LanguageContext';


// ==========================================
// STATUS OPTIONS
// ==========================================

const STATUS_OPTIONS = [
  'pending',
  'approved',
  'rejected',
  'completed',
];


// ==========================================
// STATUS STYLE
// ==========================================

const getStatusStyle = (status) => {
  switch (
    String(status || '')
      .toLowerCase()
      .trim()
  ) {
    case 'approved':
      return 'bg-green-100 text-green-700 border-green-200';

    case 'rejected':
      return 'bg-red-100 text-red-700 border-red-200';

    case 'completed':
      return 'bg-blue-100 text-blue-700 border-blue-200';

    case 'pending':
    default:
      return 'bg-yellow-100 text-yellow-700 border-yellow-200';
  }
};


// ==========================================
// FORMAT DATE
// ==========================================

const formatDate = (
  date,
  language
) => {
  if (!date) {
    return '-';
  }

  const parsedDate =
    new Date(date);

  if (
    Number.isNaN(
      parsedDate.getTime()
    )
  ) {
    return '-';
  }

  try {
    return parsedDate.toLocaleString(
      language === 'km'
        ? 'km-KH'
        : 'en-GB',
      {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      }
    );
  } catch (error) {
    return parsedDate.toLocaleString();
  }
};


// ==========================================
// ADMIN ENROLLMENTS
// ==========================================

const AdminEnrollments = () => {

  // ========================================
  // LANGUAGE
  // ========================================

  const {
    t,
    language,
  } = useLanguage();


  const isKhmer =
    language === 'km' ||
    language === 'kh';


  // ========================================
  // STATES
  // ========================================

  const [
    enrollments,
    setEnrollments,
  ] = useState([]);


  const [
    loading,
    setLoading,
  ] = useState(true);


  const [
    error,
    setError,
  ] = useState('');


  const [
    search,
    setSearch,
  ] = useState('');


  const [
    selectedEnrollment,
    setSelectedEnrollment,
  ] = useState(null);


  const [
    deletingId,
    setDeletingId,
  ] = useState(null);


  const [
    updatingId,
    setUpdatingId,
  ] = useState(null);


  // ========================================
  // GET STATUS LABEL
  // ========================================

  const getStatusLabel = (
    status
  ) => {
    const safeStatus =
      String(
        status || 'pending'
      )
        .toLowerCase()
        .trim();

    const allowedStatus =
      STATUS_OPTIONS.includes(
        safeStatus
      )
        ? safeStatus
        : 'pending';

    return t(
      `enrollments.statuses.${allowedStatus}`
    );
  };


  // ========================================
  // GET COURSE NAME
  // ========================================

  const getCourseName = (
    enrollment
  ) => {
    const course =
      enrollment?.course;

    if (course) {
      if (isKhmer) {
        return (
          course.title_km ||
          course.title_en ||
          course.title ||
          `${t('enrollments.course')} #${
            enrollment?.course_id || '-'
          }`
        );
      }

      return (
        course.title_en ||
        course.title_km ||
        course.title ||
        `${t('enrollments.course')} #${
          enrollment?.course_id || '-'
        }`
      );
    }

    return (
      `${t(
        'enrollments.course'
      )} #${
        enrollment?.course_id ||
        '-'
      }`
    );
  };


  // ========================================
  // FETCH ENROLLMENTS
  // ========================================

  const fetchEnrollments =
    useCallback(
      async () => {
        try {
          setLoading(true);

          setError('');

          const response =
            await api.get(
              '/api/enrollments/'
            );

          const data =
            response.data;

          if (
            Array.isArray(data)
          ) {
            setEnrollments(
              data
            );
          } else if (
            Array.isArray(
              data?.items
            )
          ) {
            setEnrollments(
              data.items
            );
          } else {
            setEnrollments(
              []
            );
          }

        } catch (err) {
          console.error(
            'Fetch enrollments error:',
            err
          );

          setError(
            getApiErrorMessage(
              err,
              t(
                'enrollments.loadFailed'
              )
            )
          );

        } finally {
          setLoading(false);
        }
      },
      [t]
    );


  // ========================================
  // LOAD DATA
  // ========================================

  useEffect(() => {
    fetchEnrollments();
  }, [fetchEnrollments]);


  // ========================================
  // FILTER / SEARCH
  // ========================================

  const filteredEnrollments =
    useMemo(() => {
      const keyword =
        search
          .toLowerCase()
          .trim();

      if (!keyword) {
        return enrollments;
      }

      return enrollments.filter(
        (item) => {
          const values = [
            item.id,
            item.student_name,
            item.student_email,
            item.student_phone,
            item.status,
            item.course_id,

            item.course?.title,

            item.course?.title_en,

            item.course?.title_km,

            getCourseName(item),
          ];

          return values.some(
            (value) =>
              String(
                value || ''
              )
                .toLowerCase()
                .includes(
                  keyword
                )
          );
        }
      );
    }, [
      enrollments,
      search,
      language,
    ]);


  // ========================================
  // STATUS COUNTS
  // ========================================

  const totalCount =
    enrollments.length;


  const pendingCount =
    enrollments.filter(
      (item) =>
        String(
          item.status ||
          'pending'
        )
          .toLowerCase()
          .trim() ===
        'pending'
    ).length;


  const approvedCount =
    enrollments.filter(
      (item) =>
        String(
          item.status || ''
        )
          .toLowerCase()
          .trim() ===
        'approved'
    ).length;


  const completedCount =
    enrollments.filter(
      (item) =>
        String(
          item.status || ''
        )
          .toLowerCase()
          .trim() ===
        'completed'
    ).length;


  // ========================================
  // UPDATE STATUS
  // ========================================

  const handleStatusChange =
    async (
      enrollment,
      newStatus
    ) => {
      const oldStatus =
        String(
          enrollment.status ||
          'pending'
        )
          .toLowerCase()
          .trim();

      if (
        oldStatus ===
        newStatus
      ) {
        return;
      }

      try {
        setUpdatingId(
          enrollment.id
        );

        setError('');

        const response =
          await api.patch(
            `/api/enrollments/${enrollment.id}/status`,
            {
              status:
                newStatus,
            }
          );

        const updatedEnrollment =
          response.data;

        setEnrollments(
          (current) =>
            current.map(
              (item) =>
                item.id ===
                enrollment.id
                  ? {
                      ...item,
                      ...updatedEnrollment,

                      status:
                        updatedEnrollment
                          ?.status ||
                        newStatus,
                    }
                  : item
            )
        );

        setSelectedEnrollment(
          (current) => {
            if (
              !current ||
              current.id !==
                enrollment.id
            ) {
              return current;
            }

            return {
              ...current,
              ...updatedEnrollment,

              status:
                updatedEnrollment
                  ?.status ||
                newStatus,
            };
          }
        );

      } catch (err) {
        console.error(
          'Update status error:',
          err
        );

        setError(
          getApiErrorMessage(
            err,
            t(
              'enrollments.updateStatusFailed'
            )
          )
        );

      } finally {
        setUpdatingId(
          null
        );
      }
    };


  // ========================================
  // DELETE ENROLLMENT
  // ========================================

  const handleDelete =
    async (
      enrollment
    ) => {
      const studentName =
        enrollment.student_name ||
        t(
          'enrollments.student'
        );

      const confirmed =
        window.confirm(
          `${t(
            'enrollments.deleteConfirm'
          )} "${studentName}"?`
        );

      if (!confirmed) {
        return;
      }

      try {
        setDeletingId(
          enrollment.id
        );

        setError('');

        await api.delete(
          `/api/enrollments/${enrollment.id}`
        );

        setEnrollments(
          (current) =>
            current.filter(
              (item) =>
                item.id !==
                enrollment.id
            )
        );

        if (
          selectedEnrollment?.id ===
          enrollment.id
        ) {
          setSelectedEnrollment(
            null
          );
        }

      } catch (err) {
        console.error(
          'Delete enrollment error:',
          err
        );

        setError(
          getApiErrorMessage(
            err,
            t(
              'enrollments.deleteFailed'
            )
          )
        );

      } finally {
        setDeletingId(
          null
        );
      }
    };


  // ========================================
  // LOADING
  // ========================================

  if (loading) {
    return (
      <div
        className={`
          min-h-[400px]

          flex
          items-center
          justify-center

          ${
            isKhmer
              ? 'font-khmer'
              : 'font-english'
          }
        `}
      >
        <div
          className="
            text-center
          "
        >
          <div
            className="
              w-12
              h-12

              mx-auto

              rounded-full

              border-4
              border-blue-100
              border-t-blue-900

              animate-spin
            "
          />

          <p
            className="
              mt-4

              text-gray-500
              font-medium
            "
          >
            {t(
              'enrollments.loading'
            )}
          </p>
        </div>
      </div>
    );
  }


  // ========================================
  // MAIN
  // ========================================

  return (
    <div
      className={`
        w-full

        ${
          isKhmer
            ? 'font-khmer'
            : 'font-english'
        }
      `}
    >

      {/* ==================================
          PAGE HEADER
      ================================== */}

      <div
        className="
          flex
          flex-col

          sm:flex-row
          sm:items-center
          sm:justify-between

          gap-4

          mb-7
        "
      >
        <div
          className="
            flex
            items-center
            gap-3
          "
        >
          <div
            className="
              w-12
              h-12

              rounded-xl

              bg-blue-900

              flex
              items-center
              justify-center

              shadow-md
            "
          >
            <FiUsers
              className="
                w-6
                h-6

                text-white
              "
            />
          </div>

          <div>
            <h1
              className="
                text-2xl
                sm:text-3xl

                font-bold

                text-blue-900
              "
            >
              {t(
                'enrollments.title'
              )}
            </h1>

            <p
              className="
                text-sm
                sm:text-base

                text-gray-500

                mt-1
              "
            >
              {t(
                'enrollments.subtitle'
              )}
            </p>
          </div>
        </div>


        <button
          type="button"

          onClick={
            fetchEnrollments
          }

          className="
            inline-flex
            items-center
            justify-center
            gap-2

            px-4
            py-2.5

            rounded-xl

            bg-blue-900
            text-white

            font-semibold

            hover:bg-blue-800

            transition-all
            duration-200

            shadow-sm
            hover:shadow-md
          "
        >
          <FiRefreshCw
            className="
              w-4
              h-4
            "
          />

          {t(
            'enrollments.refresh'
          )}
        </button>
      </div>


      {/* ==================================
          ERROR
      ================================== */}

      {
        error && (
          <div
            className="
              mb-6

              px-4
              py-3

              bg-red-50

              border
              border-red-200

              rounded-xl

              text-red-700
              text-sm
            "
          >
            {error}
          </div>
        )
      }


      {/* ==================================
          STATS
      ================================== */}

      <div
        className="
          grid
          grid-cols-1

          sm:grid-cols-2
          xl:grid-cols-4

          gap-4

          mb-6
        "
      >
        <StatCard
          title={
            t(
              'enrollments.totalEnrollments'
            )
          }
          value={
            totalCount
          }
        />

        <StatCard
          title={
            t(
              'enrollments.pending'
            )
          }
          value={
            pendingCount
          }
        />

        <StatCard
          title={
            t(
              'enrollments.approved'
            )
          }
          value={
            approvedCount
          }
        />

        <StatCard
          title={
            t(
              'enrollments.completed'
            )
          }
          value={
            completedCount
          }
        />
      </div>


      {/* ==================================
          SEARCH
      ================================== */}

      <div
        className="
          bg-white

          border
          border-blue-100

          rounded-2xl

          shadow-sm

          p-4

          mb-5
        "
      >
        <div
          className="
            relative

            max-w-xl
          "
        >
          <FiSearch
            className="
              absolute

              left-4
              top-1/2

              -translate-y-1/2

              w-5
              h-5

              text-gray-400
            "
          />

          <input
            type="text"

            value={
              search
            }

            onChange={
              (event) =>
                setSearch(
                  event.target.value
                )
            }

            placeholder={
              t(
                'enrollments.searchPlaceholder'
              )
            }

            className="
              w-full

              pl-12
              pr-10

              py-3

              border
              border-blue-200

              rounded-xl

              bg-white

              text-gray-700

              placeholder:text-gray-400

              focus:outline-none
              focus:ring-2
              focus:ring-blue-900/20
              focus:border-blue-900

              transition-all
              duration-200
            "
          />

          {
            search && (
              <button
                type="button"

                onClick={() =>
                  setSearch('')
                }

                className="
                  absolute

                  right-3
                  top-1/2

                  -translate-y-1/2

                  w-8
                  h-8

                  flex
                  items-center
                  justify-center

                  rounded-lg

                  text-gray-400

                  hover:text-red-600
                  hover:bg-red-50

                  transition-colors
                "
              >
                <FiX
                  className="
                    w-4
                    h-4
                  "
                />
              </button>
            )
          }
        </div>
      </div>


      {/* ==================================
          TABLE
      ================================== */}

      <div
        className="
          bg-white

          border
          border-blue-100

          rounded-2xl

          shadow-sm

          overflow-hidden
        "
      >
        <div
          className="
            overflow-x-auto
          "
        >
          <table
            className="
              w-full
              min-w-[1000px]
            "
          >
            <thead
              className="
                bg-blue-50

                border-b
                border-blue-100
              "
            >
              <tr>
                <TableHead>
                  #
                </TableHead>

                <TableHead>
                  {t(
                    'enrollments.student'
                  )}
                </TableHead>

                <TableHead>
                  {t(
                    'enrollments.contact'
                  )}
                </TableHead>

                <TableHead>
                  {t(
                    'enrollments.course'
                  )}
                </TableHead>

                <TableHead>
                  {t(
                    'enrollments.status'
                  )}
                </TableHead>

                <TableHead>
                  {t(
                    'enrollments.date'
                  )}
                </TableHead>

                <TableHead>
                  {t(
                    'enrollments.actions'
                  )}
                </TableHead>
              </tr>
            </thead>


            <tbody
              className="
                divide-y
                divide-blue-50
              "
            >
              {
                filteredEnrollments
                  .length === 0
                  ? (
                    <tr>
                      <td
                        colSpan="7"

                        className="
                          px-6
                          py-16

                          text-center
                        "
                      >
                        <FiUsers
                          className="
                            w-12
                            h-12

                            mx-auto

                            text-gray-300

                            mb-3
                          "
                        />

                        <p
                          className="
                            font-semibold
                            text-gray-700
                          "
                        >
                          {t(
                            'enrollments.noEnrollments'
                          )}
                        </p>

                        <p
                          className="
                            text-sm
                            text-gray-400

                            mt-1
                          "
                        >
                          {t(
                            'enrollments.noEnrollmentsDescription'
                          )}
                        </p>
                      </td>
                    </tr>
                  )
                  : (
                    filteredEnrollments.map(
                      (
                        enrollment,
                        index
                      ) => {
                        const status =
                          String(
                            enrollment.status ||
                            'pending'
                          )
                            .toLowerCase()
                            .trim();

                        return (
                          <tr
                            key={
                              enrollment.id
                            }

                            className="
                              hover:bg-blue-50/40

                              transition-colors
                              duration-150
                            "
                          >

                            {/* NUMBER */}

                            <td
                              className="
                                px-5
                                py-4

                                text-sm
                                text-gray-500
                              "
                            >
                              {index + 1}
                            </td>


                            {/* STUDENT */}

                            <td
                              className="
                                px-5
                                py-4
                              "
                            >
                              <div
                                className="
                                  flex
                                  items-center
                                  gap-3
                                "
                              >
                                <div
                                  className="
                                    w-10
                                    h-10

                                    rounded-xl

                                    bg-blue-100

                                    flex
                                    items-center
                                    justify-center

                                    flex-shrink-0
                                  "
                                >
                                  <FiUsers
                                    className="
                                      w-5
                                      h-5

                                      text-blue-900
                                    "
                                  />
                                </div>

                                <div>
                                  <p
                                    className="
                                      font-semibold
                                      text-gray-900
                                    "
                                  >
                                    {
                                      enrollment.student_name ||
                                      '-'
                                    }
                                  </p>

                                  <p
                                    className="
                                      text-xs
                                      text-gray-400

                                      mt-0.5
                                    "
                                  >
                                    ID #{enrollment.id}
                                  </p>
                                </div>
                              </div>
                            </td>


                            {/* CONTACT */}

                            <td
                              className="
                                px-5
                                py-4
                              "
                            >
                              <div
                                className="
                                  space-y-1.5
                                "
                              >
                                <div
                                  className="
                                    flex
                                    items-center
                                    gap-2

                                    text-sm
                                    text-gray-600
                                  "
                                >
                                  <FiMail
                                    className="
                                      w-4
                                      h-4

                                      text-blue-500
                                    "
                                  />

                                  <span>
                                    {
                                      enrollment.student_email ||
                                      '-'
                                    }
                                  </span>
                                </div>

                                <div
                                  className="
                                    flex
                                    items-center
                                    gap-2

                                    text-sm
                                    text-gray-600
                                  "
                                >
                                  <FiPhone
                                    className="
                                      w-4
                                      h-4

                                      text-green-600
                                    "
                                  />

                                  <span>
                                    {
                                      enrollment.student_phone ||
                                      '-'
                                    }
                                  </span>
                                </div>
                              </div>
                            </td>


                            {/* COURSE */}

                            <td
                              className="
                                px-5
                                py-4
                              "
                            >
                              <div
                                className="
                                  flex
                                  items-start
                                  gap-2
                                "
                              >
                                <FiBookOpen
                                  className="
                                    w-4
                                    h-4

                                    mt-1

                                    text-blue-900

                                    flex-shrink-0
                                  "
                                />

                                <div>
                                  <p
                                    className="
                                      text-sm
                                      font-semibold
                                      text-gray-800
                                    "
                                  >
                                    {
                                      getCourseName(
                                        enrollment
                                      )
                                    }
                                  </p>

                                  <p
                                    className="
                                      text-xs
                                      text-gray-400

                                      mt-0.5
                                    "
                                  >
                                    {
                                      t(
                                        'enrollments.courseId'
                                      )
                                    }:{' '}
                                    {
                                      enrollment.course_id ||
                                      '-'
                                    }
                                  </p>
                                </div>
                              </div>
                            </td>


                            {/* STATUS */}

                            <td
                              className="
                                px-5
                                py-4
                              "
                            >
                              <div
                                className="
                                  flex
                                  flex-col
                                  gap-2
                                "
                              >
                                <span
                                  className={`
                                    inline-flex
                                    items-center
                                    justify-center

                                    w-fit

                                    px-2.5
                                    py-1

                                    rounded-full

                                    border

                                    text-xs
                                    font-semibold

                                    ${getStatusStyle(
                                      status
                                    )}
                                  `}
                                >
                                  {
                                    getStatusLabel(
                                      status
                                    )
                                  }
                                </span>

                                <select
                                  value={
                                    status
                                  }

                                  disabled={
                                    updatingId ===
                                    enrollment.id
                                  }

                                  onChange={
                                    (event) =>
                                      handleStatusChange(
                                        enrollment,
                                        event.target.value
                                      )
                                  }

                                  className="
                                    min-w-[145px]

                                    px-3
                                    py-2

                                    border
                                    border-gray-200

                                    rounded-lg

                                    bg-white

                                    text-sm
                                    text-gray-700

                                    focus:outline-none
                                    focus:ring-2
                                    focus:ring-blue-900/20
                                    focus:border-blue-900

                                    disabled:opacity-50
                                    disabled:cursor-not-allowed
                                  "
                                >
                                  {
                                    STATUS_OPTIONS.map(
                                      (
                                        option
                                      ) => (
                                        <option
                                          key={
                                            option
                                          }

                                          value={
                                            option
                                          }
                                        >
                                          {
                                            getStatusLabel(
                                              option
                                            )
                                          }
                                        </option>
                                      )
                                    )
                                  }
                                </select>
                              </div>
                            </td>


                            {/* DATE */}

                            <td
                              className="
                                px-5
                                py-4
                              "
                            >
                              <div
                                className="
                                  flex
                                  items-start
                                  gap-2

                                  text-sm
                                  text-gray-600
                                "
                              >
                                <FiCalendar
                                  className="
                                    w-4
                                    h-4

                                    mt-0.5

                                    text-blue-500

                                    flex-shrink-0
                                  "
                                />

                                <span>
                                  {
                                    formatDate(
                                      enrollment.created_at,
                                      language
                                    )
                                  }
                                </span>
                              </div>
                            </td>


                            {/* ACTIONS */}

                            <td
                              className="
                                px-5
                                py-4
                              "
                            >
                              <div
                                className="
                                  flex
                                  items-center
                                  gap-2
                                "
                              >
                                <button
                                  type="button"

                                  title={
                                    t(
                                      'enrollments.viewDetails'
                                    )
                                  }

                                  onClick={() =>
                                    setSelectedEnrollment(
                                      enrollment
                                    )
                                  }

                                  className="
                                    w-9
                                    h-9

                                    rounded-lg

                                    bg-blue-50
                                    text-blue-900

                                    flex
                                    items-center
                                    justify-center

                                    hover:bg-blue-900
                                    hover:text-white

                                    transition-all
                                    duration-200
                                  "
                                >
                                  <FiEye
                                    className="
                                      w-4
                                      h-4
                                    "
                                  />
                                </button>


                                <button
                                  type="button"

                                  title={
                                    t(
                                      'common.delete'
                                    )
                                  }

                                  disabled={
                                    deletingId ===
                                    enrollment.id
                                  }

                                  onClick={() =>
                                    handleDelete(
                                      enrollment
                                    )
                                  }

                                  className="
                                    w-9
                                    h-9

                                    rounded-lg

                                    bg-red-50
                                    text-red-600

                                    flex
                                    items-center
                                    justify-center

                                    hover:bg-red-600
                                    hover:text-white

                                    transition-all
                                    duration-200

                                    disabled:opacity-50
                                    disabled:cursor-not-allowed
                                  "
                                >
                                  {
                                    deletingId ===
                                    enrollment.id
                                      ? (
                                        <FiRefreshCw
                                          className="
                                            w-4
                                            h-4

                                            animate-spin
                                          "
                                        />
                                      )
                                      : (
                                        <FiTrash2
                                          className="
                                            w-4
                                            h-4
                                          "
                                        />
                                      )
                                  }
                                </button>
                              </div>
                            </td>
                          </tr>
                        );
                      }
                    )
                  )
              }
            </tbody>
          </table>
        </div>
      </div>


      {/* ==================================
          VIEW MODAL
      ================================== */}

      {
        selectedEnrollment && (
          <div
            className="
              fixed
              inset-0

              z-50

              flex
              items-center
              justify-center

              bg-black/50

              p-4
            "
          >
            <div
              className={`
                bg-white

                w-full
                max-w-2xl

                max-h-[90vh]

                overflow-y-auto

                rounded-2xl

                shadow-2xl

                ${
                  isKhmer
                    ? 'font-khmer'
                    : 'font-english'
                }
              `}
            >

              {/* MODAL HEADER */}

              <div
                className="
                  flex
                  items-center
                  justify-between

                  gap-4

                  px-6
                  py-5

                  bg-blue-900

                  rounded-t-2xl
                "
              >
                <div
                  className="
                    flex
                    items-center
                    gap-3
                  "
                >
                  <div
                    className="
                      w-10
                      h-10

                      rounded-xl

                      bg-white/10

                      flex
                      items-center
                      justify-center
                    "
                  >
                    <FiUsers
                      className="
                        w-5
                        h-5

                        text-white
                      "
                    />
                  </div>

                  <div>
                    <h2
                      className="
                        text-lg
                        sm:text-xl

                        font-bold
                        text-white
                      "
                    >
                      {t(
                        'enrollments.enrollmentDetails'
                      )}
                    </h2>

                    <p
                      className="
                        text-xs
                        text-white/60

                        mt-0.5
                      "
                    >
                      {
                        t(
                          'enrollments.enrollment'
                        )
                      }{' '}
                      #{selectedEnrollment.id}
                    </p>
                  </div>
                </div>


                <button
                  type="button"

                  onClick={() =>
                    setSelectedEnrollment(
                      null
                    )
                  }

                  className="
                    w-9
                    h-9

                    rounded-lg

                    flex
                    items-center
                    justify-center

                    text-white/70

                    hover:bg-white/10
                    hover:text-white

                    transition-colors
                  "
                >
                  <FiX
                    className="
                      w-5
                      h-5
                    "
                  />
                </button>
              </div>


              {/* MODAL BODY */}

              <div
                className="
                  p-6

                  space-y-6
                "
              >
                <div
                  className="
                    grid
                    grid-cols-1
                    sm:grid-cols-2

                    gap-6
                  "
                >
                  <DetailItem
                    icon={
                      FiUsers
                    }

                    label={
                      t(
                        'enrollments.studentName'
                      )
                    }

                    value={
                      selectedEnrollment.student_name
                    }
                  />


                  <DetailItem
                    icon={
                      FiMail
                    }

                    label={
                      t(
                        'enrollments.email'
                      )
                    }

                    value={
                      selectedEnrollment.student_email
                    }
                  />


                  <DetailItem
                    icon={
                      FiPhone
                    }

                    label={
                      t(
                        'enrollments.phone'
                      )
                    }

                    value={
                      selectedEnrollment.student_phone
                    }
                  />


                  <DetailItem
                    icon={
                      FiBookOpen
                    }

                    label={
                      t(
                        'enrollments.course'
                      )
                    }

                    value={
                      getCourseName(
                        selectedEnrollment
                      )
                    }
                  />


                  <DetailItem
                    icon={
                      FiCalendar
                    }

                    label={
                      t(
                        'enrollments.enrollmentDate'
                      )
                    }

                    value={
                      formatDate(
                        selectedEnrollment.created_at,
                        language
                      )
                    }
                  />


                  <div>
                    <p
                      className="
                        text-sm
                        font-medium
                        text-gray-500

                        mb-2
                      "
                    >
                      {t(
                        'enrollments.status'
                      )}
                    </p>

                    <select
                      value={
                        String(
                          selectedEnrollment.status ||
                          'pending'
                        )
                          .toLowerCase()
                          .trim()
                      }

                      disabled={
                        updatingId ===
                        selectedEnrollment.id
                      }

                      onChange={
                        (event) =>
                          handleStatusChange(
                            selectedEnrollment,
                            event.target.value
                          )
                      }

                      className="
                        w-full

                        px-3
                        py-2.5

                        border
                        border-gray-200

                        rounded-xl

                        bg-white

                        text-gray-700

                        focus:outline-none
                        focus:ring-2
                        focus:ring-blue-900/20
                        focus:border-blue-900

                        disabled:opacity-50
                        disabled:cursor-not-allowed
                      "
                    >
                      {
                        STATUS_OPTIONS.map(
                          (
                            option
                          ) => (
                            <option
                              key={
                                option
                              }

                              value={
                                option
                              }
                            >
                              {
                                getStatusLabel(
                                  option
                                )
                              }
                            </option>
                          )
                        )
                      }
                    </select>
                  </div>
                </div>


                {/* MESSAGE */}

                <div>
                  <label
                    className="
                      block

                      text-sm
                      font-semibold
                      text-gray-500

                      mb-2
                    "
                  >
                    {t(
                      'enrollments.message'
                    )}
                  </label>

                  <div
                    className="
                      bg-gray-50

                      border
                      border-gray-200

                      rounded-xl

                      p-4

                      text-gray-700

                      whitespace-pre-wrap

                      min-h-[100px]
                    "
                  >
                    {
                      selectedEnrollment.message ||
                      t(
                        'enrollments.noMessage'
                      )
                    }
                  </div>
                </div>
              </div>


              {/* MODAL FOOTER */}

              <div
                className="
                  flex
                  flex-col-reverse
                  sm:flex-row

                  justify-end

                  gap-3

                  px-6
                  py-4

                  border-t
                  border-gray-200
                "
              >
                <button
                  type="button"

                  onClick={() =>
                    setSelectedEnrollment(
                      null
                    )
                  }

                  className="
                    px-5
                    py-2.5

                    border
                    border-gray-300

                    rounded-xl

                    text-gray-700

                    font-semibold

                    hover:bg-gray-50

                    transition-colors
                  "
                >
                  {t(
                    'common.close'
                  )}
                </button>


                <button
                  type="button"

                  disabled={
                    deletingId ===
                    selectedEnrollment.id
                  }

                  onClick={() =>
                    handleDelete(
                      selectedEnrollment
                    )
                  }

                  className="
                    inline-flex
                    items-center
                    justify-center
                    gap-2

                    px-5
                    py-2.5

                    bg-red-600
                    text-white

                    rounded-xl

                    font-semibold

                    hover:bg-red-700

                    transition-colors

                    disabled:opacity-50
                    disabled:cursor-not-allowed
                  "
                >
                  {
                    deletingId ===
                    selectedEnrollment.id
                      ? (
                        <>
                          <FiRefreshCw
                            className="
                              w-4
                              h-4

                              animate-spin
                            "
                          />

                          {t(
                            'enrollments.deleting'
                          )}
                        </>
                      )
                      : (
                        <>
                          <FiTrash2
                            className="
                              w-4
                              h-4
                            "
                          />

                          {t(
                            'common.delete'
                          )}
                        </>
                      )
                  }
                </button>
              </div>
            </div>
          </div>
        )
      }
    </div>
  );
};


// ==========================================
// STAT CARD
// ==========================================

const StatCard = ({
  title,
  value,
}) => {
  return (
    <div
      className="
        bg-white

        border
        border-blue-100

        rounded-2xl

        p-5

        shadow-sm

        hover:shadow-md

        transition-all
        duration-200
      "
    >
      <p
        className="
          text-sm
          font-medium
          text-gray-500
        "
      >
        {title}
      </p>

      <p
        className="
          text-3xl
          font-bold
          text-blue-900

          mt-2
        "
      >
        {value}
      </p>
    </div>
  );
};


// ==========================================
// TABLE HEAD
// ==========================================

const TableHead = ({
  children,
}) => {
  return (
    <th
      className="
        px-5
        py-4

        text-left

        text-xs
        font-bold

        uppercase
        tracking-wider

        text-blue-500

        whitespace-nowrap
      "
    >
      {children}
    </th>
  );
};


// ==========================================
// DETAIL ITEM
// ==========================================

const DetailItem = ({
  icon: Icon,
  label,
  value,
}) => {
  return (
    <div
      className="
        flex
        items-start
        gap-4
      "
    >
      <div
        className="
          w-10
          h-10

          rounded-xl

          bg-blue-50

          flex
          items-center
          justify-center

          flex-shrink-0
        "
      >
        <Icon
          className="
            w-5
            h-5

            text-blue-900
          "
        />
      </div>

      <div
        className="
          min-w-0
        "
      >
        <p
          className="
            text-sm
            font-medium
            text-gray-500
          "
        >
          {label}
        </p>

        <p
          className="
            text-gray-900
            font-medium

            mt-1

            break-words
          "
        >
          {value || '-'}
        </p>
      </div>
    </div>
  );
};


export default AdminEnrollments;
